// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { appTeams, notesFavorites, notesNav, notesSecondary, notesWorkspaces } from "@/blocks/sidebar-shared/sidebar-data";
import { NavSecondary } from "@/blocks/sidebar-shared/sidebar-nav-app";
import { NavFavorites, NavLinks, NavWorkspaces } from "@/blocks/sidebar-shared/sidebar-nav-notes";
import { TeamSwitcher } from "@/blocks/sidebar-shared/sidebar-team-switcher";
import { Sidebar, SidebarContent, SidebarHeader, SidebarRail } from "@/components/ui/sidebar";
export const SidebarLeft = defineUi<UI.ComponentProps<typeof Sidebar>>("SidebarLeft", [], (_props, {
  slots: _slots
}) => {
  const props = computed(() => omitProps(_props, []));
  return () => {
    return <Sidebar role="navigation" aria-label="Notes" {...domProps(props.value)}>
      <SidebarHeader>
        <TeamSwitcher teams={appTeams} compact />
        <NavLinks items={notesNav} />
      </SidebarHeader>
      <SidebarContent>
        <NavFavorites favorites={notesFavorites} />
        <NavWorkspaces workspaces={notesWorkspaces} />
        <NavSecondary items={notesSecondary} class="mt-auto" />
      </SidebarContent>
      <SidebarRail />
    </Sidebar>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { appUser, calendarGroups } from "@/blocks/sidebar-shared/sidebar-data";
import { Calendars, DatePicker } from "@/blocks/sidebar-shared/sidebar-calendar";
import { NavUser } from "@/blocks/sidebar-shared/sidebar-user-menu";
import { Icon } from "@/components/ui/icon";
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarSeparator } from "@/components/ui/sidebar";
import { Tape } from "@/components/ui/tape";
import { cn } from "@/lib/utils";
export const SidebarRight = defineUi<UI.ComponentProps<typeof Sidebar> & {
  date: Date;
  onDateChange: (date: Date) => void;
  visible: string[];
  onVisibleChange: (next: string[]) => void;
  contained?: boolean;
}>("SidebarRight", ["date", "onDateChange", "visible", "onVisibleChange", "contained", "class"], (_props, {
  slots: _slots
}) => {
  const date = computed(() => _props["date"]);
  const onDateChange = computed(() => _props["onDateChange"]);
  const visible = computed(() => _props["visible"]);
  const onVisibleChange = computed(() => _props["onVisibleChange"]);
  const contained = computed(() => _props["contained"] === undefined ? false : _props["contained"]);
  const className = computed(() => _props["class"]);
  const props = computed(() => omitProps(_props, ["date", "onDateChange", "visible", "onVisibleChange", "contained", "class"]));
  return () => {
    return <Sidebar collapsible="none" role="navigation" aria-label="Calendars" class={cn("sticky top-0 hidden border-s border-sidebar-border pt-3 lg:flex", contained.value ? "h-full" as const : "h-svh" as const, className.value)} {...domProps(props.value)}>
      <Tape kind="washi-stripes" color="tangerine" length={72} height={18} angle={-2} class="absolute top-0 start-1/2 -ms-9" />
      <SidebarHeader class="h-16 border-b border-sidebar-border">
        <NavUser user={appUser} align="start" />
      </SidebarHeader>
      <SidebarContent>
        <DatePicker selected={date.value} onSelect={next => next && onDateChange.value(next)} />
        <SidebarSeparator class="mx-0" />
        <Calendars groups={calendarGroups} value={visible.value} onValueChange={onVisibleChange.value} />
      </SidebarContent>
      <SidebarFooter>
        <SidebarMenu>
          <SidebarMenuItem>
            <SidebarMenuButton>
              <Icon name="plus" />
              <span>New calendar</span>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarFooter>
    </Sidebar>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, shallowRef } from "vue";
import { SidebarLeft } from "@/blocks/sidebar-15/components/sidebar-15-sidebar-left";
import { SidebarRight } from "@/blocks/sidebar-15/components/sidebar-15-sidebar-right";
import { containedClasses } from "@/blocks/sidebar-shared/sidebar-contained";
import { formatDay } from "@/blocks/sidebar-shared/sidebar-data";
import { PageBody, PageHeader, PageNote, PageSheet } from "@/blocks/sidebar-shared/sidebar-page";
import { SidebarProvider } from "@/components/ui/sidebar";
import { cn } from "@/lib/utils";
const START = new Date(2026, 8, 25);
const DEFAULT_VISIBLE = ["Personal", "Work", "Holidays"];
const Page = defineUi<{
  contained?: boolean;
}>("Page", ["contained"], (_props, {
  slots: _slots
}) => {
  const contained = computed(() => _props["contained"] === undefined ? false : _props["contained"]);
  const c = computed(() => containedClasses(contained.value));
  const date = shallowRef(initialState(START));
  const setDate = stateSetter(date);
  const visible = shallowRef(initialState(DEFAULT_VISIBLE));
  const setVisible = stateSetter(visible);
  return () => {
    return <SidebarProvider class={cn("overflow-clip", c.value.provider)}>
      <SidebarLeft class={c.value.sidebar} />
      <PageSheet class={c.value.inset}>
        <PageHeader crumbs={["Project plan & to-dos"]} sticky />
        <PageBody title="Project plan & to-dos" kicker={formatDay(date.value)}>
          <PageNote title="Two pads, one page" pose="carry">
            Notes on the left, your week on the right. <span class="max-lg:hidden">Pick a day in the month and the kicker above follows.</span>
            <span class="lg:hidden">Widen the window and the week pad opens.</span>
          </PageNote>
        </PageBody>
      </PageSheet>
      <SidebarRight contained={contained.value} date={date.value} onDateChange={setDate} visible={visible.value} onVisibleChange={setVisible} />
    </SidebarProvider>;
  };
});
export default Page;
